package com.bank.evolution.model;

import java.math.BigDecimal;

// Version 2 adds 'channel' WITH A DEFAULT → backward + forward compatible.
public class TxnV2 {
    private final String txnId;
    private final String accountId;
    private final BigDecimal amount;
    private final String channel; // new field, defaulted when absent

    public TxnV2(String txnId, String accountId, BigDecimal amount, String channel) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
        this.channel = channel == null ? "UNKNOWN" : channel; // default
    }
    public String getTxnId() { return txnId; }
    public String getAccountId() { return accountId; }
    public BigDecimal getAmount() { return amount; }
    public String getChannel() { return channel; }
}
