package com.bank.evolution.registry;

import java.util.*;
import java.util.logging.Logger;

// Minimal Schema Registry: versioned fields + compatibility check.
public class SchemaRegistry {
    private static final Logger log = Logger.getLogger(SchemaRegistry.class.getName());

    // subject → list of schema versions (each version = set of fields with 'hasDefault' flag)
    private final Map<String, List<Map<String, Boolean>>> subjects = new HashMap<>();

    // Register a new version if it is compatible with the latest.
    public boolean register(String subject, Map<String, Boolean> newSchema) {
        List<Map<String, Boolean>> versions = subjects.computeIfAbsent(subject, k -> new ArrayList<>());
        if (!versions.isEmpty()) {
            Map<String, Boolean> latest = versions.get(versions.size() - 1);
            if (!isCompatible(latest, newSchema)) {
                log.severe(() -> "REJECTED incompatible schema for " + subject);
                return false;
            }
        }
        versions.add(newSchema);
        log.info(() -> "REGISTERED " + subject + " v" + versions.size());
        return true;
    }

    // FULL compatibility: new fields must have defaults; no field may change meaning.
    private boolean isCompatible(Map<String, Boolean> oldS, Map<String, Boolean> newS) {
        for (String f : newS.keySet()) {
            if (!oldS.containsKey(f) && !newS.get(f)) {
                // added a field WITHOUT a default → breaks forward compatibility
                return false;
            }
        }
        return true;
    }
}
