package com.bank.evolution.columnar;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Demonstrates column pruning: read ONLY the amount column.
public class ColumnarReader {
    private static final Logger log = Logger.getLogger(ColumnarReader.class.getName());

    public BigDecimal sumAmountColumn(List<BigDecimal> amountColumn) {
        log.info("COLUMN PRUNING: reading only the amount column (" + amountColumn.size() + " cells)");
        BigDecimal total = BigDecimal.ZERO;
        for (BigDecimal a : amountColumn) total = total.add(a);
        return total;
    }
}
