package com.bank.evolution;

import com.bank.evolution.columnar.ColumnarReader;
import com.bank.evolution.model.*;
import com.bank.evolution.registry.SchemaRegistry;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class EvolutionDemo {
    private static final Logger log = Logger.getLogger(EvolutionDemo.class.getName());

    public static void main(String[] args) {
        SchemaRegistry registry = new SchemaRegistry();

        // V1: three fields, none needing defaults (baseline).
        Map<String, Boolean> v1 = new LinkedHashMap<>();
        v1.put("txnId", true); v1.put("accountId", true); v1.put("amount", true);
        registry.register("bank.txn", v1);

        // V2: add 'channel' WITH a default → compatible.
        Map<String, Boolean> v2 = new LinkedHashMap<>(v1);
        v2.put("channel", true); // hasDefault = true
        registry.register("bank.txn", v2);

        // Bad change: add 'mandatoryTag' WITHOUT a default → rejected.
        Map<String, Boolean> bad = new LinkedHashMap<>(v2);
        bad.put("mandatoryTag", false);
        registry.register("bank.txn", bad);

        log.info("=== Old and new consumers both work ===");
        TxnV1 old = new TxnV1("T1", "SAV2001", new BigDecimal("1200"));
        TxnV2 neu = new TxnV2("T2", "CUR3001", new BigDecimal("5000"), null); // channel defaults
        log.info("Old record channel (implicit) = UNKNOWN; new record channel = " + neu.getChannel());

        log.info("=== Columnar analytics: column pruning ===");
        List<BigDecimal> amountColumn = List.of(old.getAmount(), neu.getAmount());
        log.info("SUM(amount) = " + new ColumnarReader().sumAmountColumn(amountColumn));
    }
}
